package main
import("bytes";"crypto/hmac";"crypto/rand";"crypto/sha256";"encoding/hex";"fmt";"io";"net/http";"os";"strconv";"time")
func sign(secret string, value []byte) string { m:=hmac.New(sha256.New,[]byte(secret));m.Write(value);return hex.EncodeToString(m.Sum(nil)) }
func main(){
 path:="/v1/locations/loc_example/bills/INV-1001"; body:=[]byte(`{"external_table_id":"12","version":1,"currency":"PKR","status":"open","order_status":"accepted","items":[{"external_item_id":"I1","name":"Meal","quantity":1,"unit_amount":10000,"total_amount":10000}],"totals":{"subtotal":10000,"tax":0,"service_charge":0,"discount":0,"tip":0,"grand_total":10000},"occurred_at":"2026-07-18T10:30:00Z","metadata":{}}`); ts:=strconv.FormatInt(time.Now().Unix(),10)
 req,_:=http.NewRequest("PUT","https://sandbox-api.restec.io"+path,bytes.NewReader(body)); nonce:=make([]byte,16);rand.Read(nonce)
 req.Header.Set("Authorization","Bearer "+os.Getenv("RESTEC_API_KEY"));req.Header.Set("Content-Type","application/json");req.Header.Set("X-Restec-Timestamp",ts);req.Header.Set("X-Restec-Signature","v1="+sign(os.Getenv("RESTEC_REQUEST_SIGNING_SECRET"),append([]byte(ts+".PUT."+path+"."),body...)));req.Header.Set("X-Request-Id","req_"+hex.EncodeToString(nonce));req.Header.Set("Idempotency-Key","bill-INV-1001-v1")
 response,err:=(&http.Client{Timeout:5*time.Second}).Do(req);if err!=nil{panic(err)};defer response.Body.Close();if response.StatusCode/100!=2{b,_:=io.ReadAll(response.Body);panic(fmt.Sprintf("Restec %d: %s",response.StatusCode,b))}
 paymentPath:=path+"/payment-sessions";paymentBody:=[]byte(`{"amount_minor":10000,"currency":"PKR","method":"card"}`);paymentTs:=strconv.FormatInt(time.Now().Unix(),10);paymentReq,_:=http.NewRequest("POST","https://sandbox-api.restec.io"+paymentPath,bytes.NewReader(paymentBody));paymentReq.Header.Set("Authorization","Bearer "+os.Getenv("RESTEC_API_KEY"));paymentReq.Header.Set("Content-Type","application/json");paymentReq.Header.Set("X-Restec-Environment","sandbox");paymentReq.Header.Set("X-Restec-Timestamp",paymentTs);paymentReq.Header.Set("X-Restec-Signature","v1="+sign(os.Getenv("RESTEC_REQUEST_SIGNING_SECRET"),append([]byte(paymentTs+".POST."+paymentPath+"."),paymentBody...)));paymentReq.Header.Set("X-Request-Id","req_"+hex.EncodeToString(nonce));paymentReq.Header.Set("Idempotency-Key","hosted-payment-INV-1001-1");paymentResponse,err:=(&http.Client{Timeout:5*time.Second}).Do(paymentReq);if err!=nil||paymentResponse.StatusCode!=201{panic("Restec payment session failed")};paymentResponse.Body.Close() // Parse checkout_url; wait for signed webhook.
 seen:=map[string]bool{} // Replace with a database unique constraint and invoice update transaction.
 http.HandleFunc("/integrations/restec/webhooks",func(w http.ResponseWriter,r *http.Request){raw,_:=io.ReadAll(r.Body);eventTs,_:=strconv.ParseInt(r.Header.Get("X-Restec-Timestamp"),10,64);expected:="v1="+sign(os.Getenv("RESTEC_WEBHOOK_SIGNING_SECRET"),append([]byte(strconv.FormatInt(eventTs,10)+"."),raw...));if abs(time.Now().Unix()-eventTs)>300||!hmac.Equal([]byte(expected),[]byte(r.Header.Get("X-Restec-Signature"))){w.WriteHeader(401);return};id:=r.Header.Get("X-Restec-Event-Id");if !seen[id]{seen[id]=true};w.WriteHeader(202)});http.ListenAndServe(":8443",nil)
}
func abs(v int64)int64{if v<0{return -v};return v}
